

UPDATE medicamentos SET producto_id = (SELECT id FROM productos WHERE codigo = 'MED-PARA500')
WHERE principio_activo_id = (SELECT id FROM principios_activos WHERE dci = 'Paracetamol')
  AND concentracion = '500 mg' AND forma_farmaceutica = 'Tableta';

